%% ---------- Einstellungen -----------------------------------
t=data(:,1);
iq=data(:,2);
uq=data(:,3);
tk      = 0.100;        % Time of shorting [s]
Tfit    = 0.020;        % 20ms time range for fitting

Fs=1e5;     % Sampling frequency

Window = round(Fs/60); % one netperiod

%% ---------- Voltage before shorting ------------------------

idx0 = find(t<tk,1,'last');
Uq0 = abs(uq(idx0));

%% ---------- Envelope of iq --------------------------------------

[iq_env,~] = envelope((iq),Window,'peak');
plot(t,iq_env);
hold on

%% ---------- time range for fitting 0..20ms -------------------------------------

idx = t>=tk & t<=(tk+Tfit);

tt = t(idx)-tk;
hold off
yq = iq_env(idx);
plot(tt,yq)
%% ---------- Exponentialfit ----------------------------------

ft = fittype('a*exp(-x/b)+c',...
    'independent','x',...
    'coefficients',{'a','b','c'});

fitq = fit(tt,yq,ft,...
    'StartPoint',[yq(1)-yq(end) 0.02 yq(end)]);

%% ---------- Starting values at time=0 ------------------------------------

Iq0 = fitq.a + fitq.c;

%% ---------- Reaktance --------------------------------------

xq2 = Uq0/Iq0;

%% ---------- Output -----------------------------------------

fprintf('\n');
fprintf('---------------------------------\n');
fprintf('xq'''' = %.4f pu\n',xq2);
fprintf('---------------------------------\n');

%% ---------- Plots -------------------------------------

figure

plot(t,iq,'b')
hold on
plot(t,iq_env,'r','LineWidth',2)
plot(tt+tk,fitq(tt),'k--','LineWidth',2)

grid on
xlabel('Zeit [s]')
ylabel('i_q')

legend('Signal','Envelope','Fit')

title(sprintf('x_q'''' = %.4f pu',xq2))